head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
scwin.gDepCd = js_dep_cd;
scwin.gEmpNo = js_emp_no;
scwin.gLdMktTp = js_market;
scwin.acpt_num = '';
scwin.noti_seq = '';
scwin.isur_cd = '';
scwin.dep_cd = '';
scwin.gLastJob = '';
scwin.vScrenID = 'ULDSTF10803.xml';
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.initPage = function() {
    scwin.noti_seq = frame.opener.dts_Grid.getCellData(frame.opener.key_row, 'NOTI_SEQ');
    scwin.isur_cd = frame.opener.dts_Grid.getCellData(frame.opener.key_row, 'ISUR_CD');
    scwin.dep_cd = scwin.gDepCd;
    $c.stf.setObjectValue(txb_NOTI_SEQ, scwin.noti_seq);
    $c.stf.setObjectValue(txb_ISUR_CD, scwin.isur_cd);
    $c.stf.showObj(txb_NOTI_SEQ, false);
    $c.stf.showObj(txb_ISUR_CD, false);
    $c.stf.showObj(txb_DEP_CD, false);
    $c.stf.showObj(txb_MODE, false);
    $c.stf.showObj(txb_EMP_NO, false);
    //showObj(txb_DUTY_YN, false);

    //반송은 공시팀만 가능하다. 다른팀은 반송사유,반송버튼은 보이지 않게 한다.
    // 상품관리팀 20130415 상품 관리팀 제외.
    //if(gDepCd == '2220' || gDepCd == '2430' || gDepCd == '2B20') {
    if (scwin.gDepCd == '2220' || scwin.gDepCd == '2430') {
        $c.stf.showObj(label_6, false);
        $c.stf.showObj(txb_RET_RSN, false);
        $c.stf.showObj(btn_Return, false);
        panel_1.style.height = 190;
        btn_Transmit.style.top = 157;
    }
};
scwin.fn_SetCode = function() {
    //dts_MASTER.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=KIFRS_LIST";

};
scwin.fn_read = function() {
    var url = "/OnlineNotice.do?method=readDetailOnlineNoticeMaster";
    url += "&NOTI_SEQ=" + $c.stf.getObjectValue(txb_NOTI_SEQ);
    url += "&ISUR_CD=" + $c.stf.getObjectValue(txb_ISUR_CD);
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    dts_MASTER.DataID = encodeURI(url);
    dts_MASTER.Reset();
};
scwin.fn_Transmit = function(mode) {
    //T : 전송, R 반송

    if (mode == 'T') {
        scwin.gLastJob = "접수";
        $c.stf.setObjectValue(txb_MODE, "T");
        $c.stf.setObjectValue(txb_RET_RSN, "");
    } else {
        scwin.gLastJob = "반송";
        $c.stf.setObjectValue(txb_MODE, "R");
        if ($c.stf.getObjectValue(txb_RET_RSN) == '') {
            $c.win.alert("반송시 반송사유를 입력하셔야 합니다.");
            txb_RET_RSN.focus();
            return;
        }
    }
    //당번여부 셋팅
    var duty_yn = "N";
    if (js_duty == "Y" || js_duty_chrg == "Y") {
        duty_yn = "Y";
    }
    $c.stf.setObjectValue(txb_DUTY_YN, duty_yn);
    $c.stf.setObjectValue(txb_NOTI_SEQ, scwin.noti_seq);
    $c.stf.setObjectValue(txb_ISUR_CD, scwin.isur_cd);
    $c.stf.setObjectValue(txb_DEP_CD, scwin.dep_cd);
    $c.stf.setObjectValue(txb_EMP_NO, scwin.gEmpNo);
    var res = window.confirm("[" + scwin.gLastJob + "]하시겠습니까?");
    if (res) {
        var url = "/OnlineNotice.do?method=notiTeamAcpt" + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
        //alert(dts_MASTER.Text);
        trs_Save.Action = url;
        trs_Save.KeyName = "toinb_dataid4";
        trs_Save.KeyValue = "JSP(I:pInputMaster=dts_MASTER)";
        trs_Save.post();
    }
};
scwin.alert_error2 = function(dtsObj) {
    var USER_DEFINE = new Array("INTERNAL", "UNDEFINED", "APP_COMPONENT", "BIZ_COMPONENT", "ACTION", "CORE_FRAMEWORK", "WEB_FRAMEWORK", "INFO");
    for (var i = 0; i < USER_DEFINE.length; i++) {
        var errorCount = dtsObj.SrvErrCount(USER_DEFINE[i]);
        var j;
        for (j = 0; j < errorCount; j++) {
            if (dtsObj.SrvErrCode(USER_DEFINE[i], j) == '0') {
                //'0' 임의로 떨군 INFO 메시지
                $c.win.alert(dtsObj.SrvErrMsg(USER_DEFINE[i], j));
            } else {
                //기존 에러 메시지
                $c.win.alert("[CODE: " + dtsObj.SrvErrCode(USER_DEFINE[i], j) + "] " + dtsObj.SrvErrMsg(USER_DEFINE[i], j));
            }
        }
    }
};
scwin.btn_Transmit_onclick = function() {
    scwin.fn_Transmit('T');
};
scwin.btn_Return_onclick = function() {
    scwin.fn_Transmit('R');
};
scwin.trs_Save_OnFail = function() {
    scwin.alert_error2(trs_Save);
};
scwin.trs_Save_OnSuccess = async function() {
    var msg = $c.stf.getMessageParam("MSG-A001", scwin.gLastJob);
    $c.win.alert(msg);
    /*
    var fr_fn_read = frame.Provider("../").fn_read;
    frame.CloseFrame();
    fr_fn_read();
    */
    var fr_fn_search = $c.frame.path("../").fn_Search;
    await $c.frame.CloseFrame();
    fr_fn_search();
};
scwin.gform_onload = function() {
    scwin.initPage();
    $c.cm.PanelToGroupBox(panel_1);
    scwin.fn_read();
};
